// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/inventory/config", wrapper.GetInventoryConfig)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/inventory/config", wrapper.PutInventoryConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/stock", wrapper.ListStock)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/stock/{sku_id}", wrapper.GetStock)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/stock/{sku_id}/receive", wrapper.ReceiveStock)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/stock/{sku_id}/adjust", wrapper.AdjustStock)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/stock/{sku_id}/low-threshold", wrapper.SetLowThreshold)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/stock/{sku_id}/reservations", wrapper.ListSKUReservations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/stock/{sku_id}/history", wrapper.ListStockHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/reservations/{id}/release", wrapper.AdminReleaseReservation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/reservations", wrapper.ReserveStock)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/reservations/{id}/commit", wrapper.CommitReservation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/internal/reservations/{id}/release", wrapper.ReleaseReservation)
	})

	return r
}

