// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetInventoryConfig Get the shop's inventory settings
	// (GET /admin/inventory/config)
	GetInventoryConfig(ctx context.Context, request GetInventoryConfigRequestObject) (GetInventoryConfigResponseObject, error)
	// PutInventoryConfig Replace the shop's inventory settings
	// (PUT /admin/inventory/config)
	PutInventoryConfig(ctx context.Context, request PutInventoryConfigRequestObject) (PutInventoryConfigResponseObject, error)
	// AdminReleaseReservation Release a reservation by hand
	// (POST /admin/reservations/{id}/release)
	AdminReleaseReservation(ctx context.Context, request AdminReleaseReservationRequestObject) (AdminReleaseReservationResponseObject, error)
	// ListStock List stock levels
	// (GET /admin/stock)
	ListStock(ctx context.Context, request ListStockRequestObject) (ListStockResponseObject, error)
	// GetStock Get a SKU's stock
	// (GET /admin/stock/{sku_id})
	GetStock(ctx context.Context, request GetStockRequestObject) (GetStockResponseObject, error)
	// AdjustStock Adjust stock
	// (POST /admin/stock/{sku_id}/adjust)
	AdjustStock(ctx context.Context, request AdjustStockRequestObject) (AdjustStockResponseObject, error)
	// ListStockHistory List a SKU's stock movements
	// (GET /admin/stock/{sku_id}/history)
	ListStockHistory(ctx context.Context, request ListStockHistoryRequestObject) (ListStockHistoryResponseObject, error)
	// SetLowThreshold Set the low-stock threshold
	// (PUT /admin/stock/{sku_id}/low-threshold)
	SetLowThreshold(ctx context.Context, request SetLowThresholdRequestObject) (SetLowThresholdResponseObject, error)
	// ReceiveStock Receive stock
	// (POST /admin/stock/{sku_id}/receive)
	ReceiveStock(ctx context.Context, request ReceiveStockRequestObject) (ReceiveStockResponseObject, error)
	// ListSKUReservations List a SKU's active reservations
	// (GET /admin/stock/{sku_id}/reservations)
	ListSKUReservations(ctx context.Context, request ListSKUReservationsRequestObject) (ListSKUReservationsResponseObject, error)
	// ReserveStock Reserve stock for a checkout session
	// (POST /internal/reservations)
	ReserveStock(ctx context.Context, request ReserveStockRequestObject) (ReserveStockResponseObject, error)
	// CommitReservation Commit a reservation
	// (POST /internal/reservations/{id}/commit)
	CommitReservation(ctx context.Context, request CommitReservationRequestObject) (CommitReservationResponseObject, error)
	// ReleaseReservation Release a reservation
	// (POST /internal/reservations/{id}/release)
	ReleaseReservation(ctx context.Context, request ReleaseReservationRequestObject) (ReleaseReservationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

